"""卵なし・敵卵ありでは、ピンチでなくても切り札で卵より先に倒す (2026-11-25).

Synthetic panels and a synthetic card kit; no ROM, input delivery, card-use
receipt, enemy summon or victory is claimed here. The condition uses only the
named general, the observed zero count (or the static eggless row) and the
enemy's static egg capability.
"""
import pytest

from docich.hanjuku_speedrun import hanjuku_policy as p
from docich.hanjuku_speedrun.hanjuku.flows import battle as flow
from docich.hanjuku_speedrun.hanjuku.judgment import battle as rules
from docich.hanjuku_speedrun.hanjuku_screen import Battle, Screen


def memory(ally='トレビス', enemy='アルファルファ', *, enemy_hp=60, ally_hp=40,
           egg=None, **cur):
    mem = {'chapter': 1, 'tick': 5, 'battle': {
        'enemy': enemy, 'ally': ally, 'enemy_hp': enemy_hp, 'ally_hp': ally_hp,
        'start_enemy_hp': enemy_hp, 'start_ally_hp': ally_hp,
        'side': 'attack', 'step': 'S1', 'castle': 'ゴーメン',
        'cards_used': [], 'cards_selected': [], 'cards_unclassified': [],
        'card_evidence_version': 1, 'planned_cards': [], 'tactics_done': [],
        'strategy_expected': None, 'context': 'message'}}
    if egg is not None:
        mem['egg_uses'] = {ally: egg}
    mem['battle'].update(cur)
    return mem


def screen(mem):
    cur = mem['battle']
    return Screen([], None, '', kind='battle', battle=Battle(
        cur['enemy'], cur['enemy_hp'], cur['ally'], cur['ally_hp']),
        field_soldiers=(0, 0))


def charted_card(mem, monkeypatch, *, after_card=None, kit_known=True):
    """Bind one charted クースカン whose HP timing has not arrived yet."""
    monkeypatch.setattr(flow, '_tactics', lambda _mem, _step: ({
        'enemy': 'アルファルファ', 'card': 'クースカン', 'when_hp_at_most': 5,
        'step': 'S1', 'tactic_id': 'egg-race:test', 'note': 'テスト札',
        **({'after_card': after_card} if after_card else {})},))
    monkeypatch.setattr(flow, '_egg_drop_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_strong_card_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_carried_opening_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_egg_plan', lambda _mem, _cur: {
        'kit_known': kit_known, 'kit_source': 'order', 'dropper': None,
        'cards': [{'name': 'クースカン', 'available': 1 if kit_known else None}]})


@pytest.mark.parametrize('case,expected', [
    ('static_eggless', True), ('observed_zero', True),
    ('observed_positive', False), ('unread_count', False),
    ('enemy_without_trigger', False), ('boss', False), ('summoned', False),
    ('defense', True), ('side_unknown', False), ('recheck_pending', False),
    ('enemy_hp1', False),                  # owner 2026-11-25: HP1は資源を温存
])
def test_pressure_needs_a_named_eggless_side_and_an_egg_capable_enemy(case, expected):
    mem = memory()
    if case == 'observed_zero':
        mem = memory(ally='クミン', egg=0)
    elif case == 'observed_positive':
        mem = memory(ally='クミン', egg=2)
    elif case == 'unread_count':
        mem = memory(ally='クミン')
    elif case == 'enemy_without_trigger':
        mem = memory(enemy='ミモザ')       # has an egg, no use trigger (type 0)
    elif case == 'boss':
        mem = memory(enemy='クイーン')
    elif case == 'summoned':
        mem = memory(egg_battle=True)
    elif case == 'defense':
        mem = memory(side='defense')
    elif case == 'side_unknown':
        mem = memory(side=None)
    elif case == 'recheck_pending':
        mem = memory(ally='クミン', egg=0)
        mem['egg_recheck'] = ['クミン']    # a selection dirties the old count
    elif case == 'enemy_hp1':
        mem = memory(enemy_hp=1)
    assert rules._egg_race_pressure(mem, mem['battle']) is expected


@pytest.mark.parametrize('estimate,advances', [
    ({'effect_kind': 'half_enemy_hp', 'target_kind': 'general', 'self_harm': False}, True),
    ({'effect_kind': 'fixed', 'target_kind': 'general', 'self_harm': False,
      'raw_damage_min': 10}, True),
    ({'effect_kind': 'fixed', 'target_kind': 'general', 'self_harm': False,
      'raw_damage_min': 0}, False),
    ({'effect_kind': 'fixed', 'target_kind': 'general', 'self_harm': True,
      'raw_damage_min': 10}, False),
    ({'effect_kind': 'heal', 'target_kind': 'general', 'self_harm': False}, False),
    ({'effect_kind': 'unknown', 'target_kind': 'general', 'self_harm': False}, False),
])
def test_only_a_guaranteed_positive_effect_counts_as_pressure_progress(estimate, advances):
    assert rules._egg_race_card_advances(estimate) is advances


def test_a_control_card_is_licensed_by_the_race_but_not_by_a_healthy_battle():
    mem = memory(enemy_hp=60, ally_hp=20)   # halving still leaves the enemy ahead
    gate = rules._card_damage_gate(mem, mem['battle'], 'クースカン',
                                   listed_cards=['クースカン'])
    assert gate['allowed'] is True and gate['role'] == 'egg_race_not_a_kill'

    with_egg = memory(ally='クミン', egg=2, enemy_hp=60, ally_hp=20)
    refused = rules._card_damage_gate(with_egg, with_egg['battle'], 'クースカン',
                                      listed_cards=['クースカン'])
    assert refused['allowed'] is False
    assert refused['role'] == 'control_has_no_observed_followup'


def test_a_self_harm_card_is_not_licensed_by_the_race():
    mem = memory(enemy_hp=60, ally_hp=20)
    gate = rules._card_damage_gate(mem, mem['battle'], 'バグストーム',
                                   listed_cards=['バグストーム'])
    assert gate['allowed'] is False


def test_the_charted_health_timing_is_overridden_only_under_the_race(monkeypatch):
    mem = memory()
    charted_card(mem, monkeypatch)
    assert p.battle_step(screen(mem), mem) == [p.pad('b')]
    cur = mem['battle']
    assert cur['card_flow']['card'] == 'クースカン'
    assert 'チャートの時期を待たず使用' in cur['card_flow']['note']
    planned = [r for r in mem.get('_records', []) if r['decision'] == 'battle_card']
    assert planned and planned[-1]['egg_race_pressure'] is True

    with_egg = memory(ally='クミン', egg=2)
    charted_card(with_egg, monkeypatch)
    p.battle_step(screen(with_egg), with_egg)
    assert (with_egg['battle'].get('card_flow') or {}).get('card') != 'クースカン'
    assert not any(r['decision'] == 'battle_card' for r in with_egg.get('_records', []))


def test_a_chain_second_card_still_waits_for_its_first_card(monkeypatch):
    mem = memory()
    charted_card(mem, monkeypatch, after_card='クースカン')
    p.battle_step(screen(mem), mem)
    assert not (mem['battle'].get('card_flow') or {}).get('card')


def test_an_unknown_kit_never_forces_a_card(monkeypatch):
    mem = memory()
    charted_card(mem, monkeypatch, kit_known=False)
    p.battle_step(screen(mem), mem)
    assert not (mem['battle'].get('card_flow') or {}).get('card')
    assert not any(r['decision'] == 'battle_card' for r in mem.get('_records', []))


def _bound(monkeypatch, cards):
    monkeypatch.setattr(flow, '_order_for_step',
                        lambda _mem, step: {'step': step, 'general': 'トレビス',
                                            'cards': list(cards)})
    monkeypatch.setattr(flow, 'bound_fields',
                        lambda _order, _mem: {'general': 'トレビス', 'cards': list(cards)})


def test_a_carried_card_charted_for_another_enemy_opens_under_the_race(monkeypatch):
    _bound(monkeypatch, ['クースカン'])
    mem = memory()
    other_enemy = [{'enemy': 'ミント', 'card': 'クースカン', 'step': 'S1',
                    'when_hp_at_most': 5, 'tactic_id': 'x', 'note': 'x'}]
    assert flow._carried_opening_tactics(mem, mem['battle'], other_enemy) == []
    forced = flow._carried_opening_tactics(mem, mem['battle'], other_enemy, pressure=True)
    assert [t['card'] for t in forced] == ['クースカン']
    assert forced[0]['egg_race'] is True and forced[0]['open'] is True

    same_enemy = [{**other_enemy[0], 'enemy': 'アルファルファ'}]
    assert flow._carried_opening_tactics(
        mem, mem['battle'], same_enemy, pressure=True) == []
